#!/usr/bin/env python3
"""IPv6 pipeline-FIB compiler and image lookup.

Reads one JSON request per line on stdin and writes exactly one JSON
response per line on stdout.
"""

import ctypes
import json
import os
import re
import sys
from math import gcd

MASK128 = (1 << 128) - 1

# ---------------------------------------------------------------- addresses --

_HEX = {}
for _i, _c in enumerate('0123456789abcdef'):
    _HEX[_c] = _i
for _i, _c in enumerate('ABCDEF'):
    _HEX[_c] = _i


def parse_addr(s):
    """Parse an IPv6 address in pure hexadecimal colon notation."""
    n = len(s)
    if n == 0 or n > 39:
        return None
    i = s.find('::')
    if i >= 0:
        if s.find('::', i + 1) >= 0:
            return None
        lg = s[:i].split(':') if i else ()
        right = s[i + 2:]
        rg = right.split(':') if right else ()
        tail = 8 - len(lg) - len(rg)
        if tail < 1:
            return None
        val = 0
        for g in lg:
            if not g or len(g) > 4:
                return None
            v = 0
            for ch in g:
                d = _HEX.get(ch)
                if d is None:
                    return None
                v = (v << 4) | d
            val = (val << 16) | v
        val <<= 16 * tail
        for g in rg:
            if not g or len(g) > 4:
                return None
            v = 0
            for ch in g:
                d = _HEX.get(ch)
                if d is None:
                    return None
                v = (v << 4) | d
            val = (val << 16) | v
        return val
    parts = s.split(':')
    if len(parts) != 8:
        return None
    val = 0
    for g in parts:
        if not g or len(g) > 4:
            return None
        v = 0
        for ch in g:
            d = _HEX.get(ch)
            if d is None:
                return None
            v = (v << 4) | d
        val = (val << 16) | v
    return val


def fmt_addr(v):
    """Canonical pure-hex rendering of a 128-bit address value."""
    g = [(v >> sh) & 0xffff for sh in (112, 96, 80, 64, 48, 32, 16, 0)]
    bi = -1
    bl = 1
    i = 0
    while i < 8:
        if g[i] == 0:
            j = i + 1
            while j < 8 and g[j] == 0:
                j += 1
            if j - i > bl:
                bl = j - i
                bi = i
            i = j
        else:
            i += 1
    if bi < 0:
        return ':'.join('%x' % x for x in g)
    left = ':'.join('%x' % x for x in g[:bi])
    right = ':'.join('%x' % x for x in g[bi + bl:])
    if left and right:
        return left + '::' + right
    if left:
        return left + '::'
    if right:
        return '::' + right
    return '::'


def parse_prefix(s):
    """Parse 'addr/len'; returns (net, len) or None."""
    if not isinstance(s, str):
        return None
    i = s.find('/')
    if i < 0:
        return None
    if s.find('/', i + 1) >= 0:
        return None
    a = parse_addr(s[:i])
    if a is None:
        return None
    ls = s[i + 1:]
    if not ls or len(ls) > 3:
        return None
    for ch in ls:
        if ch < '0' or ch > '9':
            return None
    if ls[0] == '0' and len(ls) > 1:
        return None
    plen = int(ls)
    if plen > 128:
        return None
    mask = ((1 << plen) - 1) << (128 - plen)
    if a & ~mask:
        return None
    return (a, plen)


def fmt_prefix(net, plen):
    return fmt_addr(net) + '/' + str(plen)


def is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)

# ------------------------------------------------------------ guard parsing --

_STR_RE = re.compile(rb'"(?:[^"\\]|\\.)*"', re.S)
_BRACKET_TBL = bytes((i if i in b'[]{}' else 32) for i in range(256))
_DEPTH_RE = re.compile(rb'[\[{]{40,}')
MAX_VALUES = 3000000
MAX_LINE = 40 * 1024 * 1024


def parse_request_line(raw):
    """Strictly parse one request line; returns a dict or None."""
    if len(raw) > MAX_LINE:
        return None
    try:
        s = raw.decode('utf-8')
    except UnicodeDecodeError:
        return None
    stripped = _STR_RE.sub(b'""', raw)
    if _DEPTH_RE.search(stripped.translate(_BRACKET_TBL)) is not None:
        return None
    if (stripped.count(b':') + stripped.count(b',') +
            stripped.count(b'[') + stripped.count(b'{') + 1 > MAX_VALUES):
        return None
    try:
        obj = json.loads(s)
    except Exception:
        return None
    if not isinstance(obj, dict):
        return None
    return obj

# ------------------------------------------------------------- core access ---

_CORE = None


def load_core():
    global _CORE
    if _CORE is not None:
        return _CORE or None
    path = os.environ.get('SCAMP_CORE', '')
    if path and os.path.exists(path):
        try:
            lib = ctypes.CDLL(path)
            fn = lib.compile_core
            fn.restype = ctypes.c_int
            fn.argtypes = [
                ctypes.c_char_p, ctypes.c_char_p, ctypes.c_int, ctypes.c_int,
                ctypes.c_int, ctypes.POINTER(ctypes.c_int64),
                ctypes.POINTER(ctypes.c_int32), ctypes.POINTER(ctypes.c_int64),
                ctypes.POINTER(ctypes.c_int64), ctypes.POINTER(ctypes.c_int64)]
            _CORE = fn
            return fn
        except Exception:
            pass
    _CORE = False
    return None


def core_compile(nets, lens, caps, max_stride):
    """Returns (cuts, used) or None when no feasible placement exists."""
    fn = load_core()
    if fn is not None:
        n = len(nets)
        netbuf = b''.join(x.to_bytes(16, 'big') for x in nets)
        lensbuf = bytes(bytearray(lens))
        caparr = (ctypes.c_int64 * len(caps))(*caps)
        cuts = (ctypes.c_int32 * (len(caps) + 1))()
        used = (ctypes.c_int64 * len(caps))()
        pn = ctypes.c_int64(0)
        pd = ctypes.c_int64(0)
        rc = fn(netbuf, lensbuf, n, max_stride, len(caps), caparr,
                cuts, used, ctypes.byref(pn), ctypes.byref(pd))
        if rc == 0:
            return (list(cuts), list(used))
        if rc == 1:
            return None
    return py_compile(nets, lens, caps, max_stride)


# ------------------------------------------------- pure python core fallback --

def py_compile(nets, lens, caps, max_stride):
    n = len(nets)
    gstart = [None] * 129
    gid = [None] * 129
    nd = [0] * 129
    for d in range(129):
        gs = []
        gid_d = [-1] * n
        prevt = -1
        g = -1
        for i in range(n):
            if lens[i] <= d:
                continue
            t = 0 if d == 0 else (nets[i] >> (128 - d))
            if g < 0 or t != prevt:
                gs.append(i)
                g += 1
            gid_d[i] = g
            prevt = t
        gstart[d] = gs
        gid[d] = gid_d
        nd[d] = len(gs)
    lstart = [0] * 130
    for i in range(n):
        lstart[lens[i] + 1] += 1
    for e in range(129):
        lstart[e + 1] += lstart[e]
    lenlist = [0] * n
    fillp = list(lstart)
    for i in range(n):
        lenlist[fillp[lens[i]]] = i
        fillp[lens[i]] += 1
    has_default = any(x == 0 for x in lens)

    Ut = {}
    for b in range(128):
        nb = 1 if b == 0 else nd[b]
        cnt = [0] * nb
        acc = [0] * nb
        if b == 0 and has_default:
            cnt[0] = 1
        gsb = gstart[b]
        emax = min(128, b + max_stride)
        for e in range(b + 1, emax + 1):
            for k in range(lstart[e], lstart[e + 1]):
                i = lenlist[k]
                g = 0 if b == 0 else gid[b][i]
                cnt[g] += 1
                acc[g] += (e - b + 7) // 8
            eterm = 4 + (e - b + 7) // 8
            U = 0
            if e < 128 and nd[e] > 0:
                gse = gstart[e]
                ne = nd[e]
                j = 0
                for q in range(nb):
                    if b == 0:
                        lo, hi = 0, n
                    else:
                        lo = gsb[q]
                        hi = gsb[q + 1] if q + 1 < nd[b] else n
                    while j < ne and gse[j] < lo:
                        j += 1
                    ec = 0
                    while j < ne and gse[j] < hi:
                        j += 1
                        ec += 1
                    inner = 16 + 4 * cnt[q] + acc[q] + ec * eterm
                    U += 64 * ((inner + 7) // 8)
            else:
                for q in range(nb):
                    inner = 16 + 4 * cnt[q] + acc[q]
                    U += 64 * ((inner + 7) // 8)
            Ut[(b, e)] = U

    S = len(caps)
    dp = [[None] * 129 for _ in range(S + 1)]
    par = [[-1] * 129 for _ in range(S + 1)]
    dp[0][0] = (0, 1)
    for k in range(1, S + 1):
        dpk = dp[k]
        dpk1 = dp[k - 1]
        cap = caps[k - 1]
        for e in range(1, 129):
            best = None
            bp = -1
            lo = max(0, e - max_stride)
            for b in range(lo, e):
                p = dpk1[b]
                if p is None:
                    continue
                U = Ut.get((b, e))
                if U is None:
                    continue
                pn_, pd_ = p
                if pn_ * cap >= U * pd_:
                    rn, rd = pn_, pd_
                else:
                    rn, rd = U, cap
                if best is None or rn * best[1] < best[0] * rd:
                    best = (rn, rd)
                    bp = b
            if best is not None:
                dpk[e] = best
                par[k][e] = bp
    if dp[S][128] is None:
        return None
    e = 128
    cuts = [0] * (S + 1)
    for k in range(S, 0, -1):
        cuts[k] = e
        e = par[k][e]
    cuts[0] = 0
    used = [Ut[(cuts[i], cuts[i + 1])] for i in range(S)]
    return (cuts, used)

# ------------------------------------------------------------------ layout ---


def node_cost(nrules, acc8, nedges, eterm):
    inner = 16 + 4 * nrules + acc8 + nedges * eterm
    return 64 * ((inner + 7) // 8)


def compute_layout(nets, lens, hops, cuts, default_hop):
    """Return (stages, used).

    stages[i] = list of nodes [key, b, e, rules, ekeys, acc8] where
    rules = [(L, net, hop)] sorted by (L, net) and ekeys = sorted list of
    child keys at depth e.  After child assignment ekeys becomes
    [(key, child_index)]."""
    n = len(nets)
    S = len(cuts) - 1
    stages = []
    for i in range(S):
        b = cuts[i]
        e = cuts[i + 1]
        groups = {}
        for idx in range(n):
            if lens[idx] <= b:
                continue
            t = 0 if b == 0 else (nets[idx] >> (128 - b))
            tl = groups.get(t)
            if tl is None:
                groups[t] = [idx]
            else:
                tl.append(idx)
        if i == 0 and not groups:
            groups[0] = []
        nodes = []
        for t in sorted(groups):
            idxs = groups[t]
            rl = []
            acc8 = 0
            if i == 0 and default_hop is not None:
                rl.append((0, 0, default_hop))
            for idx in idxs:
                pl = lens[idx]
                if b < pl <= e:
                    rl.append((pl, nets[idx], hops[idx]))
                    acc8 += (pl - b + 7) // 8
            rl.sort()
            ek = []
            if e < 128:
                sh = 128 - e
                seen = set()
                for idx in idxs:
                    if lens[idx] > e:
                        seen.add(nets[idx] >> sh)
                ek = sorted(seen)
            nodes.append([t, b, e, rl, ek, acc8])
        stages.append(nodes)
    for i in range(S - 1):
        pos = {}
        for j, nd_ in enumerate(stages[i + 1]):
            pos[nd_[0]] = j
        for nd_ in stages[i]:
            nd_[4] = [(k, pos[k]) for k in nd_[4]]
    used = []
    for i in range(S):
        e = cuts[i + 1]
        eterm = 4 + (e - cuts[i] + 7) // 8
        u = 0
        for nd_ in stages[i]:
            u += node_cost(len(nd_[3]), nd_[5], len(nd_[4]), eterm)
        used.append(u)
    return stages, used


def serialize_image(caps, max_stride, cuts, stages, used, peak):
    out_stages = []
    for nodes in stages:
        out_nodes = []
        for (t, b, e, rl, ek, _acc) in nodes:
            out_nodes.append({
                'prefix': fmt_prefix(t << (128 - b), b),
                'rules': [{'prefix': fmt_prefix(net, pl), 'hop': h}
                          for (pl, net, h) in rl],
                'edges': [{'prefix': fmt_prefix(k << (128 - e), e), 'child': c}
                          for (k, c) in ek],
            })
        out_stages.append({'nodes': out_nodes})
    return {
        'status': 'ok',
        'capacities': caps,
        'max_stride': max_stride,
        'cuts': cuts,
        'stages': out_stages,
        'used_bits': used,
        'peak': {'num': peak[0], 'den': peak[1]},
    }

# ----------------------------------------------------------------- compile ---


def peak_ratio(used, caps):
    bn, bd = 0, 1
    for u, c in zip(used, caps):
        if u * bd > bn * c:
            bn, bd = u, c
    g = gcd(bn, bd)
    if g == 0:
        g = 1
    return (bn // g, bd // g)


def do_compile(req):
    if set(req.keys()) != {'op', 'fib', 'capacities', 'max_stride'}:
        return None
    fib = req['fib']
    if not isinstance(fib, list) or len(fib) > 2048:
        return None
    caps = req['capacities']
    if not isinstance(caps, list) or not (4 <= len(caps) <= 16):
        return None
    for c in caps:
        if not is_int(c) or c < 1 or c > 10 ** 9:
            return None
    ms = req['max_stride']
    if not is_int(ms) or ms < 1 or ms > 32:
        return None
    nets = []
    lens = []
    hops = []
    seen = set()
    for rec in fib:
        if not isinstance(rec, dict) or set(rec.keys()) != {'prefix', 'hop'}:
            return None
        h = rec['hop']
        if not is_int(h) or h < 0 or h > 65535:
            return None
        pr = parse_prefix(rec['prefix'])
        if pr is None:
            return None
        net, pl = pr
        if (net, pl) in seen:
            return None
        seen.add((net, pl))
        nets.append(net)
        lens.append(pl)
        hops.append(h)
    n = len(nets)
    order = sorted(range(n), key=lambda i: (nets[i], lens[i]))
    nets = [nets[i] for i in order]
    lens = [lens[i] for i in order]
    hops = [hops[i] for i in order]
    default_hop = None
    for i in range(n):
        if lens[i] == 0:
            default_hop = hops[i]
    res = core_compile(nets, lens, caps, ms)
    if res is None:
        return {'status': 'infeasible'}
    cuts, _uc = res
    stages, used = compute_layout(nets, lens, hops, cuts, default_hop)
    for i, u in enumerate(used):
        if u > caps[i]:
            return {'status': 'infeasible'}
    peak = peak_ratio(used, caps)
    return serialize_image(caps, ms, cuts, stages, used, peak)

# ----------------------------------------------------------- image checking --


def check_image(img):
    """Validate a lookup image; returns a lookup-ready structure or None."""
    if not isinstance(img, dict):
        return None
    if set(img.keys()) != {'status', 'capacities', 'max_stride', 'cuts',
                           'stages', 'used_bits', 'peak'}:
        return None
    if img['status'] != 'ok':
        return None
    caps = img['capacities']
    if not isinstance(caps, list) or not (4 <= len(caps) <= 16):
        return None
    for c in caps:
        if not is_int(c) or c < 1 or c > 10 ** 9:
            return None
    ms = img['max_stride']
    if not is_int(ms) or ms < 1 or ms > 32:
        return None
    cuts = img['cuts']
    if not isinstance(cuts, list) or len(cuts) != len(caps) + 1:
        return None
    if cuts[0] != 0 or cuts[-1] != 128:
        return None
    for i in range(len(cuts)):
        if not is_int(cuts[i]) or cuts[i] < 0 or cuts[i] > 128:
            return None
    for i in range(len(cuts) - 1):
        if cuts[i + 1] <= cuts[i] or cuts[i + 1] - cuts[i] > ms:
            return None
    stages = img['stages']
    if not isinstance(stages, list) or len(stages) != len(caps):
        return None
    used = img['used_bits']
    if not isinstance(used, list) or len(used) != len(caps):
        return None
    for u in used:
        if not is_int(u) or u < 0:
            return None
    peak = img['peak']
    if not isinstance(peak, dict) or set(peak.keys()) != {'num', 'den'}:
        return None
    if not is_int(peak['num']) or not is_int(peak['den']):
        return None
    if peak['den'] <= 0 or peak['num'] < 0:
        return None
    if peak['num'] == 0 and peak['den'] != 1:
        return None

    nrule = 0
    pstages = []
    for si, st in enumerate(stages):
        if not isinstance(st, dict) or set(st.keys()) != {'nodes'}:
            return None
        nodes = st['nodes']
        if not isinstance(nodes, list):
            return None
        b = cuts[si]
        e = cuts[si + 1]
        pnodes = []
        for nd_ in nodes:
            if not isinstance(nd_, dict):
                return None
            if set(nd_.keys()) != {'prefix', 'rules', 'edges'}:
                return None
            pr = parse_prefix(nd_['prefix'])
            if pr is None:
                return None
            nnet, nlen = pr
            if nlen != b:
                return None
            nkey = 0 if b == 0 else (nnet >> (128 - b))
            rules = nd_['rules']
            if not isinstance(rules, list):
                return None
            prules = []
            for r in rules:
                if not isinstance(r, dict):
                    return None
                if set(r.keys()) != {'prefix', 'hop'}:
                    return None
                h = r['hop']
                if not is_int(h) or h < 0 or h > 65535:
                    return None
                rp = parse_prefix(r['prefix'])
                if rp is None:
                    return None
                rnet, rlen = rp
                if rlen == 0:
                    if b != 0:
                        return None
                else:
                    if not (b < rlen <= e):
                        return None
                if (rnet >> (128 - b)) != nkey:
                    return None
                prules.append((rlen, rnet, h))
            edges = nd_['edges']
            if not isinstance(edges, list):
                return None
            pedges = []
            if e != 128:
                seen_e = set()
                for ed in edges:
                    if not isinstance(ed, dict):
                        return None
                    if set(ed.keys()) != {'prefix', 'child'}:
                        return None
                    ep = parse_prefix(ed['prefix'])
                    if ep is None:
                        return None
                    enet, elen = ep
                    if elen != e:
                        return None
                    if (enet >> (128 - b)) != nkey:
                        return None
                    ch = ed['child']
                    if not is_int(ch) or ch < 0:
                        return None
                    k = enet >> (128 - e)
                    if k in seen_e:
                        return None
                    seen_e.add(k)
                    pedges.append((k, ch))
            elif edges:
                return None
            pnodes.append([nkey, b, e, prules, pedges, 0])
            nrule += len(prules)
        for j in range(1, len(pnodes)):
            if pnodes[j][0] <= pnodes[j - 1][0]:
                return None
        pstages.append(pnodes)
    if nrule > 2048:
        return None

    nlev = len(pstages)
    for si in range(nlev - 1):
        m = len(pstages[si + 1])
        for nd_ in pstages[si]:
            for (k, ch) in nd_[4]:
                if ch >= m:
                    return None

    # rebuild the canonical layout from the collected rules and compare
    nets = []
    lens = []
    hops = []
    seen = set()
    for st in pstages:
        for nd_ in st:
            for (rlen, rnet, h) in nd_[3]:
                if (rnet, rlen) in seen:
                    return None
                seen.add((rnet, rlen))
                nets.append(rnet)
                lens.append(rlen)
                hops.append(h)
    order = sorted(range(len(nets)), key=lambda i: (nets[i], lens[i]))
    nets_s = [nets[i] for i in order]
    lens_s = [lens[i] for i in order]
    hops_s = [hops[i] for i in order]
    default_hop = None
    for i in range(len(nets_s)):
        if lens_s[i] == 0:
            default_hop = hops_s[i]
    exp_stages, exp_used = compute_layout(nets_s, lens_s, hops_s, cuts,
                                          default_hop)
    for si in range(nlev):
        a = pstages[si]
        bb = exp_stages[si]
        if len(a) != len(bb):
            return None
        for j in range(len(a)):
            if a[j][0] != bb[j][0]:
                return None
            if a[j][3] != bb[j][3]:
                return None
            if a[j][4] != bb[j][4]:
                return None
    for si in range(nlev):
        eterm = 4 + (cuts[si + 1] - cuts[si] + 7) // 8
        u = 0
        for nd_ in pstages[si]:
            acc8 = 0
            for (rlen, rnet, h) in nd_[3]:
                acc8 += (rlen - cuts[si] + 7) // 8
            u += node_cost(len(nd_[3]), acc8, len(nd_[4]), eterm)
        if u != used[si]:
            return None
    for i in range(len(caps)):
        if used[i] > caps[i]:
            return None
    pn, pd = peak_ratio(used, caps)
    if pn != peak['num'] or pd != peak['den']:
        return None

    # build fast lookup structures
    fast = []
    for si in range(nlev):
        e = cuts[si + 1]
        sh = 128 - e
        fnodes = []
        for nd_ in pstages[si]:
            rd = {}
            lens_desc = []
            for (rlen, rnet, h) in nd_[3]:
                d = rd.get(rlen)
                if d is None:
                    d = {}
                    rd[rlen] = d
                    lens_desc.append(rlen)
                d[rnet >> (128 - rlen)] = h
            lens_desc.sort(reverse=True)
            ed = {}
            for (k, ch) in nd_[4]:
                ed[k] = ch
            fnodes.append((lens_desc, rd, ed, sh))
        fast.append(fnodes)
    return {'cuts': cuts, 'stages': fast, 'S': nlev}


def do_lookup(req):
    if set(req.keys()) != {'op', 'image', 'addresses'}:
        return None
    st = check_image(req['image'])
    if st is None:
        return None
    addrs = req['addresses']
    if not isinstance(addrs, list) or len(addrs) > 20000:
        return None
    vals = []
    for a in addrs:
        if not isinstance(a, str):
            return None
        v = parse_addr(a)
        if v is None:
            return None
        vals.append(v)
    cuts = st['cuts']
    stages = st['stages']
    S = st['S']
    answers = []
    ap = answers.append
    for v in vals:
        best_len = -1
        best_hop = None
        cur = 0
        for i in range(S):
            fnodes = stages[i]
            if cur >= len(fnodes):
                break
            lens_desc, rd, ed, sh = fnodes[cur]
            for L in lens_desc:
                if L <= best_len:
                    break
                h = rd[L].get(v >> (128 - L))
                if h is not None:
                    best_len = L
                    best_hop = h
                    break
            if i == S - 1:
                break
            nxt = ed.get(v >> sh)
            if nxt is None:
                break
            cur = nxt
        if best_len < 0:
            ap({'hop': None, 'prefix_length': None})
        else:
            ap({'hop': best_hop, 'prefix_length': best_len})
    return {'status': 'ok', 'answers': answers}

# -------------------------------------------------------------------- main ---


def process(obj):
    op = obj.get('op')
    if op == 'compile':
        return do_compile(obj)
    if op == 'lookup':
        return do_lookup(obj)
    return None


def main():
    w = sys.stdout
    for raw in sys.stdin.buffer:
        if raw.endswith(b'\n'):
            raw = raw[:-1]
        obj = None
        try:
            obj = parse_request_line(raw)
        except Exception:
            obj = None
        resp = None
        if obj is not None:
            try:
                resp = process(obj)
            except Exception:
                resp = None
        if resp is None:
            resp = {'status': 'invalid'}
        w.write(json.dumps(resp, separators=(',', ':')))
        w.write('\n')
    w.flush()


if __name__ == '__main__':
    main()
